"trigger":"event","afterMs":1000},{"id":"settle","from":"moving","to":"idle","label":"정착 후 대기","trigger":"after","afterMs":1200}]}}],"algorithms":[{"id":"power-decay","name":"Power decay","description":"값 = base * ratio^depth","params":[{"id":"base","label":"Base","description":"첫 세대 길이","value":{"type":"number","value":140,"min":20,"max":300,"step":1,"unit":"px"}},{"id":"ratio","label":"Ratio","description":"감소 비율","value":{"type":"number","value":0.7,"min":0.3,"max":0.95,"step":0.01,"unit":""}}]},{"id":"recursive-branch","name":"Recursive branch","description":"depth 세대까지 둘로 갈라지고 length로 길이를 정합니다.","params":[{"id":"depth","label":"Depth","description":"세대 수","value":{"type":"number","value":6,"min":1,"max":9,"step":1,"unit":""}},{"id":"length","label":"Length","description":"세대별 길이","value":{"type":"algorithm","algorithmId":"power-decay","args":[{"id":"base","value":{"type":"number","value":140,"min":20,"max":300,"step":1,"unit":"px"}},{"id":"ratio","value":{"type":"number","value":0.7,"min":0.3,"max":0.95,"step":0.01,"unit":""}}]}}]},{"id":"sine-wave","name":"Sine wave","description":"amplitude*sin(t*cycles)","params":[{"id":"amplitude","label":"Amplitude","description":"","value":{"type":"number","value":20,"min":0,"max":80,"step":1,"unit":"px"}}]}]},"targetNodeId":"orb","targetTransformationId":"pulse","code":"// @rulegen-module "tree"
rulegenModule("tree", function (m) {
  function algo_power_decay(base, ratio, depth) { return base * Math.pow(ratio, depth); }
  return {
    draw() {
      const box = m.box("tree"), x = box.x + box.w / 2, bottom = box.y + box.h;
      const depth = m.v("tree/structure/depth");
      const base = m.v("tree/structure/length/base"), ratio = m.v("tree/structure/length/ratio");
      p.stroke(m.v("tree/ink"));
      for (let i = 0; i < depth; i++) p.line(x, bottom - i * 10, x, bottom - i * 10 - algo_power_decay(base, ratio, i));
      const speed = m.v("orb/speed");
      p.circle(m.box("orb").x + speed * m.state("orb").elapsed / 1000, 300, m.v("orb/radius") * 2);
    },
    mousePressed() { if (m.state("orb").id === "idle") m.emit("orb", "press"); },
  };
});
// @rulegen-module-end","instruction":""}
